public class Pizzarechner {

    public static void main(String[] args) {
        int gaeste = 7;
        int pizzaStuecke = 16;

        int stueckeProGast = pizzaStuecke / gaeste;   // ganzzahlig!
        int rest = pizzaStuecke % gaeste;             // was übrig bleibt

        System.out.println("Jeder Gast bekommt " + stueckeProGast + " Stücke");
        System.out.println("Übrig bleiben " + rest + " Stücke");

        double anteil = (double) pizzaStuecke / gaeste;
        System.out.println("Exakt wären es " + anteil + " Stücke pro Gast");
    }
}

